# The approach above doesn't enforce minimum edges directly in SAT easily.
# Let's use a different approach: use a known construction or search with networkx + constraint propagation.

# Known result: The (3,7)-cage (McGee graph) has 24 vertices, girth 7, 3-regular.
# For 15 vertices, girth 7, 4-colorable with 22 edges, let's try a direct search.

# Let's use a greedy/random construction approach with verification
import random
import networkx as nx
from itertools import combinations

def has_short_cycle(G, max_len=6):
    """Check if G has any cycle of length <= max_len"""
    for v in G.nodes():
        # BFS from v, check if we find a cycle of length <= max_len
        # Use BFS up to depth max_len//2
        visited = {v: 0}
        queue = [(v, -1, 0)]
        while queue:
            node, parent, depth = queue.pop(0)
            if depth >= max_len:
                continue
            for nb in G.neighbors(node):
                if nb == parent:
                    continue
                if nb in visited:
                    cycle_len = depth + visited[nb] + 1
                    if cycle_len <= max_len:
                        return True, cycle_len
                else:
                    visited[nb] = depth + 1
                    queue.append((nb, node, depth + 1))
    return False, None

def check_girth(G):
    """Return girth of G, or infinity if acyclic"""
    if len(G.edges()) == 0:
        return float('inf')
    try:
        return nx.girth(G)
    except:
        return float('inf')

def greedy_color(G):
    coloring = nx.coloring.greedy_color(G, strategy='largest_first')
    return max(coloring.values()) + 1

# Try random construction
best = None
best_edges = 0

random.seed(42)
all_possible_edges = list(combinations(range(15), 2))

for trial in range(10000):
    G = nx.Graph()
    G.add_nodes_from(range(15))

    edges = list(all_possible_edges)
    random.shuffle(edges)

    for u, v in edges:
        G.add_edge(u, v)
        g = check_girth(G)
        if g < 7:
            G.remove_edge(u, v)
        elif G.number_of_edges() >= 22:
            # Check colorability
            nc = greedy_color(G)
            if nc <= 4:
                best = list(G.edges())
                best_edges = G.number_of_edges()
                print(f"Trial {trial}: Found graph with {best_edges} edges, {nc} colors, girth {g}")
                break

    if best and best_edges >= 22:
        break

if best:
    print(f"Solution found: {len(best)} edges")
    print(best)
else:
    print(f"Best found: {best_edges} edges")
